🐛 Describe the bug
minimal repro
import torch
from torch.utils.cpp_extension import load_inline
source = """
    #include "ATen/core/Tensor.h"
    bool is_wrapped_number(at::Tensor& ten) {
        return ten.unsafeGetTensorImpl()->is_wrapped_number();
    }
    """
check = load_inline(
    name="inline_extension", cpp_sources=[source], functions=["is_wrapped_number"]
)

class ElementwiseWhereScalarModule(torch.nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, a):
        return torch.where(a, 0.25, 0.75)

class TrivTensor(torch.Tensor):
    @staticmethod
    def __new__(cls, elem, *, requires_grad=None):
        if requires_grad is None:
            return super().__new__(cls, elem)
        else:
            return cls._make_subclass(cls, elem, requires_grad)

    @classmethod
    def __torch_dispatch__(cls, func, _types, args=(), kwargs=None):
        for arg in args:
            if isinstance(arg, cls): continue
            print(arg, check.is_wrapped_number(arg))

ElementwiseWhereScalarModule()(TrivTensor(torch.rand((10, 10))))

> tensor(0.2500) False <--- should be true
> tensor(0.7500) False <--- should be true
Note that they are floats at __torch_function__ (which you can see by going up one stack frame).
Maybe related to #74400 (not sure).
